use std::fs

struct Bst {
    root: int,
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
}

impl Bst {
    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur != -1 {
            let k = self.keys[cur]
            if x == k {
                return true
            }
            if x < k { cur = self.lefts[cur] } else { cur = self.rights[cur] }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.root == -1 {
            self.keys.push(x)
            self.lefts.push(-1)
            self.rights.push(-1)
            self.root = 0
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur]
            if x == k {
                return false
            }
            let idx = self.keys.len() as int
            if x < k {
                if self.lefts[cur] == -1 {
                    self.keys.push(x)
                    self.lefts.push(-1)
                    self.rights.push(-1)
                    self.lefts[cur] = idx
                    return true
                }
                cur = self.lefts[cur]
            } else {
                if self.rights[cur] == -1 {
                    self.keys.push(x)
                    self.lefts.push(-1)
                    self.rights.push(-1)
                    self.rights[cur] = idx
                    return true
                }
                cur = self.rights[cur]
            }
        }
    }

    fn replace(self, parent: int, cur: int, child: int) {
        if parent == -1 {
            self.root = child
        } else if self.lefts[parent] == cur {
            self.lefts[parent] = child
        } else {
            self.rights[parent] = child
        }
    }

    fn delete(self, x: int) -> bool {
        let mut parent = -1
        let mut cur = self.root
        while cur != -1 && self.keys[cur] != x {
            parent = cur
            if x < self.keys[cur] { cur = self.lefts[cur] } else { cur = self.rights[cur] }
        }
        if cur == -1 {
            return false
        }
        let l = self.lefts[cur]
        let r = self.rights[cur]
        if l == -1 {
            self.replace(parent, cur, r)
        } else if r == -1 {
            self.replace(parent, cur, l)
        } else {
            let mut sp = cur
            let mut s = r
            while self.lefts[s] != -1 {
                sp = s
                s = self.lefts[s]
            }
            self.keys[cur] = self.keys[s]
            let child = self.rights[s]
            if sp == cur {
                self.rights[sp] = child
            } else {
                self.lefts[sp] = child
            }
        }
        true
    }

    fn height_of(self, n: int) -> int {
        if n == -1 {
            return 0
        }
        let a = self.height_of(self.lefts[n])
        let b = self.height_of(self.rights[n])
        if a > b { a + 1 } else { b + 1 }
    }

    fn inorder(self) -> string {
        let mut out: Vec<string> = []
        let mut stack: Vec<int> = []
        let mut cur = self.root
        while cur != -1 || stack.len() > 0 {
            while cur != -1 {
                stack.push(cur)
                cur = self.lefts[cur]
            }
            let n = stack.pop().unwrap_or(-1)
            out.push("${self.keys[n]}")
            cur = self.rights[n]
        }
        if out.len() == 0 { "<empty>" } else { out.join(" ") }
    }
}

fn main() {
    let mut t = Bst { root: -1, keys: [], lefts: [], rights: [] }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    for line in text.split("\n") {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        let mut arg = 0
        if parts.len() > 1 {
            arg = parts[1].parse::<int>().unwrap_or(0)
        }
        if cmd == "insert" {
            if t.insert(arg) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            if t.contains(arg) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            if t.delete(arg) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height_of(t.root)}")
        } else if cmd == "min" || cmd == "max" {
            if t.root == -1 {
                println("empty")
            } else {
                let mut c = t.root
                if cmd == "min" {
                    while t.lefts[c] != -1 { c = t.lefts[c] }
                } else {
                    while t.rights[c] != -1 { c = t.rights[c] }
                }
                println("${t.keys[c]}")
            }
        }
    }
}

